"""Provided agent driver and context utilities. Students do not edit this file.

The scripted model supplies action choices. This driver calls it, routes requests
through the harness, and applies the supplied retry and stopping policy.
"""
import json
from pathlib import Path

import harness
import tools

SYSTEM = "You are a careful coding agent. Fix the failing test using the tools provided."


def _blocks(msg):
    c = msg["content"]
    return c if isinstance(c, list) else [{"type": "text", "text": c}]



def measure(messages):
    """Provided helper: estimate tokens from serialized characters, rounded up."""
    return (len(json.dumps(messages)) + 3) // 4



def compact(messages, budget):
    if measure(messages) <= budget:
        return messages
    # Keep the prompt/task and the latest request/result together.
    head, middle, tail = messages[:2], messages[2:-2], messages[-2:]
    # Match results to requests, retaining only the latest old test output.
    names = {}
    latest = None
    for m in middle:
        for b in _blocks(m):
            if b.get("type") == "tool_use":
                names[b["id"]] = b["name"]
            elif b.get("type") == "tool_result" and names.get(b["tool_use_id"]) == "run_tests":
                latest = str(b["content"])
    summary = f"[Earlier context compacted: {len(middle)} messages removed.]"
    if latest is not None:
        summary += "\nMost recent run_tests output:\n" + latest
    return head + [{"role": "user", "content": summary}] + tail



def run_loop(model, task, repo, approve, max_iterations=12, budget=None):
    messages = [{"role": "system", "content": SYSTEM}, {"role": "user", "content": task}]
    tests_hash_at_start = tools.hash_dir(Path(repo) / "tests")
    iterations = 0
    max_context_size = 0
    status = "gave_up"

    for _ in range(max_iterations):
        if budget is not None and measure(messages) > budget:
            messages = compact(messages, budget)
        max_context_size = max(max_context_size, measure(messages))
        reply = model(messages)
        iterations += 1
        messages.append(reply)
        uses = [b for b in _blocks(reply) if b.get("type") == "tool_use"]
        if uses:
            results = []
            for u in uses:
                content, is_err = harness.execute_tool(repo, u["name"], u["input"], approve)
                results.append({"type": "tool_result", "tool_use_id": u["id"],
                                "content": content, "is_error": is_err})
            messages.append({"role": "user", "content": results})
            continue
        ok, out = harness.verify(repo, tests_hash_at_start)
        if ok:
            status = "verified"
            break
        messages.append({"role": "user", "content": "Verification failed: " + out})
    return {"status": status, "iterations": iterations, "messages": messages,
            "max_context_size": max_context_size}

